import { readFile } from "node:fs/promises";
import { join } from "node:path";

import {
  RADIUS_LOCK_VERSION,
  RadiusLockSchema,
  type RadiusLock,
} from "@curve-ai/agent-contracts";
import { parse, type ParseError } from "jsonc-parser";

import { UsageError } from "./errors.js";
import type { RegistryEntry } from "./registry.js";

export const LOCK_FILENAME = "radius.lock";

const LOCK_NOTICE =
  "Generated by `radius init` from the ACP registry. Do not edit; commit it beside radius.json. `radius init --force` re-pins.";

export function lockPath(root: string): string {
  return join(root, LOCK_FILENAME);
}

export async function readRawLock(root: string): Promise<string | null> {
  try {
    return await readFile(lockPath(root), "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
}

/**
 * Parses a lock, or says why it cannot be used. The reason is returned
 * rather than thrown because the two callers want different things from a
 * broken lock: loading refuses it, while `init` simply regenerates it — it is
 * generated, so there is nothing in it worth preserving.
 */
export function parseLock(
  raw: string,
): { lock: RadiusLock } | { problem: string } {
  const errors: ParseError[] = [];
  const parsed: unknown = parse(raw, errors, { allowTrailingComma: true });
  if (errors.length > 0)
    return { problem: `${LOCK_FILENAME} is not valid JSON.` };
  const result = RadiusLockSchema.safeParse(parsed);
  if (!result.success) {
    const detail = result.error.issues
      .map((issue) => `  ${issue.path.join(".") || "(root)"}: ${issue.message}`)
      .join("\n");
    return { problem: `${LOCK_FILENAME} is not a valid lock:\n${detail}` };
  }
  return { lock: result.data };
}

export async function readLock(root: string): Promise<RadiusLock | null> {
  const raw = await readRawLock(root);
  if (raw === null) return null;
  const parsed = parseLock(raw);
  if ("problem" in parsed) {
    throw new UsageError(
      `${parsed.problem}\n\nIt is generated, so nothing in it needs keeping: run \`radius init --force\` to rewrite it.`,
    );
  }
  return parsed.lock;
}

export function lockFromEntry(entry: RegistryEntry): RadiusLock {
  return {
    "//": LOCK_NOTICE,
    lockfileVersion: RADIUS_LOCK_VERSION,
    harness: {
      registryId: entry.id,
      version: entry.version,
      ...(entry.license ? { license: entry.license } : {}),
      ...(entry.licenseUrl ? { licenseUrl: entry.licenseUrl } : {}),
      distribution: entry.distribution,
    },
  };
}

/**
 * A lock rebuilt from a pin that was written inline, before the lock existed.
 *
 * Moving a pin into the lock must not upgrade it, and the registry serves
 * only its latest version, so the inline block is the one source that still
 * knows what was pinned. The inline form never recorded a version, so it is
 * read back out of the artifacts: a release URL's `/v1.2.3/` segment, or a
 * package's `@1.2.3`. Undefined when neither is there, and the caller falls
 * back to the registry and says so.
 */
export function lockFromInline(
  block: Record<string, unknown>,
): RadiusLock | undefined {
  const parsed = RadiusLockSchema.shape.harness.safeParse({
    registryId: block.registryId,
    version: "0",
    ...(typeof block.license === "string" ? { license: block.license } : {}),
    ...(typeof block.licenseUrl === "string"
      ? { licenseUrl: block.licenseUrl }
      : {}),
    distribution: block.distribution,
  });
  if (!parsed.success) return undefined;
  const version = versionOf(parsed.data.distribution);
  if (!version) return undefined;
  return {
    "//": LOCK_NOTICE,
    lockfileVersion: RADIUS_LOCK_VERSION,
    harness: { ...parsed.data, version },
  };
}

function versionOf(
  distribution: RadiusLock["harness"]["distribution"],
): string | undefined {
  if (distribution.kind !== "binary") {
    return /@(\d[^@/]*)$/.exec(distribution.package)?.[1];
  }
  // Every platform must agree; a mixed pin has no single version to name.
  const versions = new Set(
    Object.values(distribution.platforms).map(
      (artifact) => /\/v?(\d+\.\d+\.\d+[^/]*)\//.exec(artifact.archive)?.[1],
    ),
  );
  if (versions.size !== 1) return undefined;
  return [...versions][0];
}

/**
 * Fixed key order and formatting, so the same registry entry always produces
 * the same bytes and a re-run of `init` leaves no diff to review.
 */
export function renderLock(lock: RadiusLock): string {
  return `${JSON.stringify(lock, null, 2)}\n`;
}
